describe('Search Race Condition Handling', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display only the latest search result when multiple requests are in flight', () => {
    // Intercept the search API endpoint
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // First search request (slower)
    cy.get('[data-testid="search-input"]').type('apple');
    cy.get('[data-testid="search-button"]').click();

    // Second search request (faster)
    cy.get('[data-testid="search-input"]').clear().type('banana');
    cy.get('[data-testid="search-button"]').click();

    // Wait for both requests to complete
    cy.wait('@searchRequest', { timeout: 10000 });

    // Verify that only the result from the second (latest) request is displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('contain', 'banana');
    cy.get('[data-testid="search-result-item"]').should('not.contain', 'apple');
  });

  it('should handle rapid search requests and display the correct result', () => {
    // Intercept the search API endpoint
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Rapidly type and search
    cy.get('[data-testid="search-input"]').type('a');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-input"]').clear().type('b');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-input"]').clear().type('c');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the last request to complete
    cy.wait('@searchRequest', { timeout: 10000 });

    // Verify that only the result from the last search ('c') is shown
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('contain', 'c');
    cy.get('[data-testid="search-result-item"]').should('not.contain', 'a');
    cy.get('[data-testid="search-result-item"]').should('not.contain', 'b');
  });
});
